-- Hunt warnings (hunt_warnings.lua, hunt_warnings_core.lua; tests/hunt_warnings_test.lua; server/README.md "Hunt warnings (O323)").
-- Every number of the system is here. Returned as a table, loaded as
--     dofile("data/scripts/chaos/hunt_warnings_config.lua")
-- No engine calls. Lua 5.1 / LuaJIT and Lua 5.3.
--
-- Some entries (a hole, a trapdoor, stairs, a ladder, a teleport) lead from a weak hunt to a place with much stronger,
-- denser monsters. They stay. Near each one players see a caution effect, and a red message once per player and area.
-- `places` is written by server/tools/audit_hunt_transitions.py from the map (between the markers; do not edit by hand):
--   id      the row number          kind   "teleport" or "floor" (a hole, stairs, a ladder, a rope spot)
--   pos     the entry tile          to     where the player lands
--   group   entries whose landings are close share a group (one message for the group)
--   level   the lowest level of the monsters of the destination, down to a multiple of 5
--   from    the area the entry is in (information only)    verdict   "danger" or "extreme"
local C = {}

-- The switch. false: no effect and no message.
C.enabled = true

C.tickMs = 1000 -- how often players are looked at
-- Caution effect: a magic effect on the entry tile for every player in view of it (a skull-like flash, the effect named
-- CONST_ME_<effect>; `effectId` when the engine has no such name). Every `effectEveryTicks` ticks.
C.effect = "MORTAREA"
C.effectId = 18
C.effectExtreme = "BLACKSMOKE" -- extreme entries flash a second effect beside it (nil: none)
C.effectExtremeId = 68
C.effectRadius = 7 -- players within this many tiles (same floor) see it
C.effectEveryTicks = 2
-- The red message when a player comes this close to an entry (same floor), and again on arrival at a landing.
C.warnRadius = 3
C.arriveRadius = 1
-- The same area warns the same player again after this many seconds; no two messages to a player within `minGapSeconds`.
C.cooldownSeconds = 600
C.minGapSeconds = 5
-- Player storage: os.time of the last warning shown (the gap survives a relog; Chaos.storage.huntWarnLast).
C.storage = {last = 7103050}
-- Who is not warned: players in ghost mode.
C.skipGhost = true

